<?php
require_once __DIR__.'/../bootstrap.php';$year=filter_var($_GET['anio']??date('Y'),FILTER_VALIDATE_INT);if(!$year||$year<2000||$year>2100)fail('Año inválido.',422);$st=db()->prepare('SELECT s.id AS sucursal_id,s.nombre AS sucursal,MONTH(v.fecha) AS mes,SUM(v.total) AS total FROM sucursales s LEFT JOIN ventas v ON v.sucursal_id=s.id AND YEAR(v.fecha)=? WHERE s.activa=1 GROUP BY s.id,s.nombre,MONTH(v.fecha) ORDER BY s.nombre,mes');$st->execute([$year]);$rows=$st->fetchAll();$out=[];foreach($rows as $r){$id=(int)$r['sucursal_id'];if(!isset($out[$id]))$out[$id]=['sucursal_id'=>$id,'sucursal'=>$r['sucursal'],'meses'=>array_fill(0,12,0.0),'total'=>0.0];if($r['mes']!==null){$v=(float)$r['total'];$out[$id]['meses'][(int)$r['mes']-1]=$v;$out[$id]['total']+=$v;}}respond(array_values($out));
